<?php require '../includes/db.php';require '../includes/functions.php';login_required();$id=(int)($_GET['id']??0);$uid=(int)$_SESSION['user_id'];if(($_SESSION['role']??'')==='admin'){$s=$conn->prepare('SELECT * FROM orders WHERE id=?');$s->bind_param('i',$id);}else{$s=$conn->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$s->bind_param('ii',$id,$uid);}$s->execute();$o=$s->get_result()->fetch_assoc();if(!$o)exit('Invoice not found');$it=$conn->prepare('SELECT title,price,quantity FROM order_items WHERE order_id=?');$it->bind_param('i',$id);$it->execute();$items=$it->get_result();$page_title='Invoice';include '../includes/header.php';?><div class="panel"><h1>BookNest Invoice #<?=$id?></h1><p><?=e($o['created_at'])?> · <?=e($o['status'])?></p><p><?=e($o['shipping_name'])?><br><?=e($o['shipping_address'])?><br><?=e($o['shipping_city'])?> <?=e($o['shipping_postal'])?></p><table><tr><th>Book</th><th>Price</th><th>Qty</th><th>Amount</th></tr><?php while($x=$items->fetch_assoc()):?><tr><td><?=e($x['title'])?></td><td><?=cash($x['price'])?></td><td><?=$x['quantity']?></td><td><?=cash($x['price']*$x['quantity'])?></td></tr><?php endwhile;?></table><h2>Total: <?=cash($o['total'])?></h2><button class="btn" onclick="print()">Print</button></div><?php include '../includes/footer.php';?>
